{"command": "python3 << 'PY'
import json, hashlib, os, sys
base = "/tmp/opensip-design-corrections/grok-query-reconciliation-correction-peer.v1/inputs/source"
manifest_path = "/tmp/opensip-design-corrections/grok-query-reconciliation-correction-peer.v1/inputs/source-manifest.json"
with open(manifest_path) as f:
    m = json.load(f)
print("standing:", m.get("standing"))
print("file count:", len(m["files"]))
mismatches = []
missing = []
ok = 0
for rec in m["files"]:
    p = os.path.join(base, rec["path"])
    if not os.path.isfile(p):
        missing.append(rec["path"])
        continue
    h = hashlib.sha256()
    with open(p, "rb") as fh:
        for chunk in iter(lambda: fh.read(1<<20), b""):
            h.update(chunk)
    digest = h.hexdigest()
    size = os.path.getsize(p)
    if digest != rec["sha256"] or size != rec["bytes"]:
        mismatches.append({
            "path": rec["path"],
            "expected_sha": rec["sha256"],
            "actual_sha": digest,
            "expected_bytes": rec["bytes"],
            "actual_bytes": size,
        })
    else:
        ok += 1
print("ok:", ok)
print("missing:", len(missing))
print("mismatches:", len(mismatches))
if missing:
    print("MISSING PATHS:")
    for p in missing[:50]:
        print(" ", p)
    if len(missing) > 50:
        print(" ...", len(missing)-50, "more")
if mismatches:
    print("MISMATCHES:")
    for rec in mismatches[:50]:
        print(json.dumps(rec))
    if len(mismatches) > 50:
        print(" ...", len(mismatches)-50, "more")
# also list extra files not in manifest
manifest_set = {rec["path"] for rec in m["files"]}
extra = []
for root, dirs, files in os.walk(base):
    for fn in files:
        rel = os.path.relpath(os.path.join(root, fn), base)
        if rel not in manifest_set:
            extra.append(rel)
print("extra files not in manifest:", len(extra))
if extra:
    for p in extra[:30]:
        print(" extra:", p)
